<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/auth.php'; require_once __DIR__ . '/layout.php'; require_once dirname(__DIR__) . '/services/responsibilities.php';
$current = tuman_require_role('TEACHER'); $error = null; $records = []; $students = []; $assignmentId = null;
try { $database = tuman_database(); $students = tuman_teacher_students($database, $current['id']); if (isset($_GET['assignment_id']) && $_GET['assignment_id'] !== '') { $assignmentId = tuman_teacher_assignment_id($_GET['assignment_id']); if (tuman_teacher_student($database, $current['id'], $assignmentId) === null) { http_response_code(404); exit('Responsibilities unavailable.'); } } $records = tuman_teacher_responsibilities($database, $current['id'], $assignmentId); } catch (InvalidArgumentException $exception) { http_response_code(404); exit('Responsibilities unavailable.'); } catch (Throwable $exception) { error_log('Tuman responsibility list failed: ' . $exception->getMessage()); $error = 'Responsibilities cannot be loaded right now.'; }
tuman_teacher_page_start('Responsibilities');
?>
<h1>Responsibilities</h1><p>Define clear responsibilities for you and your students.</p><form method="get"><label>Student <select name="assignment_id"><option value="">All my students</option><?php foreach ($students as $student): ?><option value="<?= (int) $student['assignment_id'] ?>"<?= $assignmentId === (int) $student['assignment_id'] ? ' selected' : '' ?>><?= htmlspecialchars(trim($student['first_name'] . ' ' . ($student['last_name'] ?? '')), ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label> <button type="submit">View</button></form><p><a class="button" href="/Tuman/teacher/responsibility-create.php">Add responsibility</a></p><?php if ($error): ?><p role="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php else: ?><div style="overflow-x:auto"><table><thead><tr><th>Student</th><th>For</th><th>Title</th><th>Details</th><th>Status</th><th>Effective dates</th><th>Actions</th></tr></thead><tbody><?php foreach ($records as $record): ?><tr><td><?= htmlspecialchars(trim($record['first_name'] . ' ' . ($record['last_name'] ?? '')), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($record['responsibility_for'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($record['title'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($record['details'] ?? '', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($record['status'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($record['effective_from'] . ($record['effective_to'] ? ' to ' . $record['effective_to'] : ''), ENT_QUOTES, 'UTF-8') ?></td><td><a href="/Tuman/teacher/responsibility-edit.php?id=<?= (int) $record['id'] ?>">Edit</a><?php if ($record['status'] === 'ACTIVE'): ?> · <a href="/Tuman/teacher/responsibility-status.php?id=<?= (int) $record['id'] ?>">Deactivate</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; tuman_teacher_page_end(); ?>
